'use client';

import { motion, AnimatePresence } from 'framer-motion';
import { useEffect, useState } from 'react';

export default function LoadingScreen() {
    const [isLoading, setIsLoading] = useState(true);

    useEffect(() => {
        // Simulate loading time (e.g., waiting for assets or just for effect)
        const timer = setTimeout(() => {
            setIsLoading(false);
        }, 3500); // 3.5 seconds total load time

        return () => clearTimeout(timer);
    }, []);

    return (
        <AnimatePresence>
            {isLoading && (
                <motion.div
                    key="loader"
                    initial={{ opacity: 1 }}
                    exit={{ opacity: 0, transition: { duration: 0.8, ease: "easeInOut" } }}
                    className="fixed inset-0 z-[9999] bg-black flex flex-col items-center justify-center pointer-events-none"
                >
                    {/* Logo Animation */}
                    <div className="relative overflow-hidden mb-12">
                        <motion.div
                            initial={{ y: 100, opacity: 0 }}
                            animate={{ y: 0, opacity: 1 }}
                            transition={{ duration: 1, ease: "circOut" }}
                            className="text-4xl md:text-6xl font-black font-heading text-white tracking-widest uppercase"
                        >
                            The Burujan
                        </motion.div>
                        <motion.div
                            initial={{ scaleX: 0 }}
                            animate={{ scaleX: 1 }}
                            transition={{ delay: 0.5, duration: 0.8, ease: "anticipate" }}
                            className="absolute bottom-0 left-0 right-0 h-1 bg-gold origin-left"
                        />
                    </div>

                    {/* Timeline / Progress Bar */}
                    <div className="w-64 md:w-96">
                        <div className="flex justify-between text-[10px] text-gray-500 font-mono mb-2 uppercase tracking-widest">
                            <span>Initializing Core</span>
                            <span>System Ready</span>
                        </div>
                        <div className="h-[2px] w-full bg-white/10 relative overflow-hidden">
                            <motion.div
                                initial={{ x: "-100%" }}
                                animate={{ x: "0%" }}
                                transition={{ duration: 3, ease: "linear" }}
                                className="absolute top-0 bottom-0 left-0 w-full bg-gold shadow-[0_0_15px_rgba(212,175,55,0.8)]"
                            />
                        </div>
                        <div className="flex justify-between mt-2">
                            <motion.span
                                initial={{ opacity: 0 }}
                                animate={{ opacity: 1 }}
                                transition={{ delay: 0.2 }}
                                className="text-[9px] text-gold font-mono"
                            >
                                :: LOADING ASSETS
                            </motion.span>
                            <motion.span
                                initial={{ opacity: 0 }}
                                animate={{ opacity: 1 }}
                                transition={{ delay: 1.5 }}
                                className="text-[9px] text-gold font-mono"
                            >
                                :: ESTABLISHING UPLINK
                            </motion.span>
                            <motion.span
                                initial={{ opacity: 0 }}
                                animate={{ opacity: 1 }}
                                transition={{ delay: 2.8 }}
                                className="text-[9px] text-green-500 font-mono"
                            >
                                :: ONLINE
                            </motion.span>
                        </div>
                    </div>
                </motion.div>
            )}
        </AnimatePresence>
    );
}
